    cb=[]; prev=0
    for l in vlines+[W]:
        if l>prev: cb.append((prev,l)); prev=l+1
    def bi(idx,bds): return next(k for k,(a_,b_) in enumerate(bds) if a_<=idx<b_)
    bycolor=defaultdict(list)
    for i in range(H):
        for j in range(W):
            if g[i][j] in (2,3): bycolor[g[i][j]].append((i,j))
    rects=[]  # (color, set of cells)
    for v,pts in bycolor.items():
        pts=set(pts)
        used=set()
        while pts:
            s=min(pts,key=lambda p:-ord(str(p)))
            comp=[s]; rem={s}
            changed=True
            while changed:
                changed=False
                for (i,j) in list(rem):
                    for (ii,jj) in comp:
                        if ii==i and jj==j: continue
                        # same row, in same row-band; or same col, same col-band
                        if ii==i and bi(i,rb)==bi(ii,rb) and bi(jj,cb)!=bi(jj,cb):
                            comp.append((ii,jj)); rem.remove((ii,jj)); changed=True; break
                        if jj==j and bi(i,rb)!=bi(ii,rb) and bi(jj,cb)==bi(jj,cb):
                            comp.append((ii,jj)); rem.remove((ii,jj)); changed=True; break
            pts-=rem
            cells=set()
            rs_=sorted(set(r for r,_ in comp)); cs_=sorted(set(c for _,c in comp))
            rbnd=min(bi(r,rb) for r in rs_); rbe=max(bi(r,rb) for r in rs_)
            cnd=min(bi(c,cb) for c in cs_); cne=max(bi(c,cb) for c in cs_)
            for rr in range(rb[rbnd][0],rb[rbe][1]):
                for cc in range(cb[cnd][0],cb[cne][1]):
                    cells.add((rr,cc))
            rects.append((v,cells))
            used|=comp
    o=[r[:] for r in g]
    for idx,(v,S) in enumerate(rects):
        for rr,jj in S:
            if g[rr][jj]!=0: continue
            covered=[k for k,(vv,SS) in enumerate(rects) if (rr,jj) in SS and vv!=v]
            if len(covered)>=1:
                o[rr][jj]=6
            else:
                o[rr][jj]=v
    return o

